import styled from '@emotion/styled';
import {
  resolveStickyTopOffset,
  stickyHeaderCoverHeight,
} from 'hooks/useStickyNavigationTopOffset/constants';

interface StyledContentCardHeaderProps {
  readonly stickyHeader?: boolean;
  readonly stickyTopOffset?: string;
}

export const StyledContentCardHeader = styled('div', {
  shouldForwardProp: (prop) =>
    prop !== 'stickyHeader' && prop !== 'stickyTopOffset',
})<StyledContentCardHeaderProps>`
  display: flex;
  justify-content: flex-start;
  flex-direction: column;
  gap: 12px;
  background: white;
  padding: 21px 24px;
  border-bottom: 1px solid #14141429;
  margin: -24px -24px 0 -24px;
  border-radius: 16px 16px 0 0;

  ${({ stickyHeader, stickyTopOffset }) =>
    stickyHeader &&
    `
      position: sticky;
      top: ${resolveStickyTopOffset(stickyTopOffset)};
      z-index: 20;
      isolation: isolate;
      border-top: inherit;

      &::before {
        content: '';
        position: absolute;
        left: -1px;
        right: -1px;
        top: calc(-1 * ${stickyHeaderCoverHeight(stickyTopOffset)});
        height: ${stickyHeaderCoverHeight(stickyTopOffset)};
        background: #f7f4ef;
        pointer-events: none;
      }

      &::after {
        content: '';
        position: absolute;
        left: -1px;
        right: -1px;
        top: 0;
        height: 24px;
        background:
          radial-gradient(
            circle at 17px 17px,
            transparent 0 17px,
            #f7f4ef 17.5px 100%
          ) left top / 18px 18px no-repeat,
          radial-gradient(
            circle at calc(100% - 17px) 17px,
            transparent 0 17px,
            #f7f4ef 17.5px 100%
          ) right top / 18px 18px no-repeat,
          linear-gradient(#f7f4ef, #f7f4ef) left 18px / 2px 0px no-repeat,
          linear-gradient(#f7f4ef, #f7f4ef) right 18px / 2px 0px no-repeat;
        pointer-events: none;
      }
    `}
`;

export const StyledContentCardHeaderTopRow = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  width: 100%;
`;

export const StyledTitleTooltipContainer = styled.div`
  display: flex;
  align-items: center;
  gap: 8px;
`;
